trd={}
dups=0
for t in tr:
    if t['rating_id'] in trd: dups+=1
    trd[t['rating_id']]=t
print('dup rating ids in transcripts', dups, 'unique', len(trd))
mism=[]
for r in rows:
    t=trd.get(r['rating_id'])
    if t is None: mism.append(('missing',r)); continue
