from collections import defaultdict, Counter
tr=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
def rat(o):
    return re.sub(r'^Displayed author: [\w-]+\. Response resp-\d+ reviewed\. ','',o).rsplit(' FINAL SCORE',1)[0]
c=defaultdict(Counter); sc=defaultdict(list)
for t in tr:
